if id=='local098':
 begin(id,{'name':'actors with film credits','keyColumns':['M_Cast.PID']},'actors', '# 独立题解（Gold揭示前）\n逐演员PID合并实际电影出演年份，从最早到最晚之间不得出现4个连续无新电影年。相邻出演年差d，中间空年为d−1；要求d≤4。一年一次/只有一年出演者在其活动职业内没有空窗，符合。出演年先DISTINCT，cast身份外围空白清理，连接Movie年后解析末4字符为整数；不按演员同名合并。另核对缺电影/无效年份和Person是否覆盖。\n')
 query(id,'parent-year-integrity',"SELECT year,COUNT(*) n FROM Movie WHERE substr(year,-4) NOT GLOB '[12][0-9][0-9][0-9]' GROUP BY year")
 base="""WITH films AS MATERIALIZED (SELECT MID,CAST(substr(year,-4) AS INTEGER) y FROM Movie),credits AS MATERIALIZED (SELECT DISTINCT TRIM(c.PID) pid,f.y FROM M_Cast c JOIN films f ON c.MID=f.MID),ordered AS (SELECT pid,y,LAG(y) OVER (PARTITION BY pid ORDER BY y) prev FROM credits),careers AS (SELECT pid,MIN(y) first_year,MAX(y) last_year,COUNT(*) years,COALESCE(MAX(y-prev),0) max_diff FROM ordered GROUP BY pid) """
 query(id,'parent-gap-distribution',base+'SELECT max_diff,COUNT(*) actors,SUM(years=1) single_year FROM careers GROUP BY max_diff ORDER BY max_diff',100)
 query(id,'parent-gap-four-examples',base+'SELECT * FROM careers WHERE max_diff=4 LIMIT 12')
 query(id,'parent-cast-orphans',"WITH pp AS MATERIALIZED(SELECT DISTINCT PID FROM Person),cc AS MATERIALIZED(SELECT DISTINCT TRIM(PID) pid FROM M_Cast) SELECT COUNT(*) actors,SUM(p.PID IS NULL) missing_person FROM cc c LEFT JOIN pp p ON c.pid=p.PID")
 spec(id,{'population.eligibility':assume('所有有可解析电影出演年记录的演员，包括只出演一年者'),'population.conditions':req(['每演员相邻出演年差不超过4；无四年连续无片窗口'],'there is no four-year span anywhere in their active career without at least a single film credit'),'population.time':req('各演员最早到最晚出演年','From the first year each actor appeared in a film to the last'),'measure.formula':assume({'op':'custom','description':'distinct PID/year -> LAG(year) -> MAX(year-prev)<=4 -> COUNT演员；单年max_diff=0'}),'measure.countGrain':assume('演员PID'),'grouping':'n/a','selection':'n/a','output':assume({'rowMode':'scalar','columns':['actors_without_four_year_gap']})})
 final_freeze(id,base+'SELECT COUNT(*) actors_without_four_year_gap FROM careers WHERE max_diff<=4',{'algorithm':'出演年差最多4等价中间最多3无片年，按PID去重','assumptions':['只出演一年者纳入','cast PID外围空白清理'],'limitations':['没有以演员同名合并身份']})
 reveal(id)
elif id=='local100':
 begin(id,{'name':'actors','keyColumns':['Person.PID']},'actors', '# 独立题解（Gold揭示前）\n合作出演构成无向演员图，Shahrukh Khan最短图距离恰好2。先查其身份PID与姓名，取其所有电影cast为一跳演员；取一跳演员出演电影的全体演员，剔除Shahrukh和一跳。同片自循环不改变最短距离。以PID计数非姓名，多路径/多影片只计一次，外围空白清理。不生成整张演员图，避免不必要平方连接。\n')
 query(id,'parent-shahrukh-identity',"SELECT PID,Name,Gender FROM Person WHERE LOWER(Name) LIKE '%shahrukh%' OR LOWER(Name) LIKE '%shah rukh%'")
 base="""WITH source AS MATERIALIZED(SELECT DISTINCT PID FROM Person WHERE TRIM(Name)='Shah Rukh Khan' OR TRIM(Name)='Shahrukh Khan'),cast_clean AS MATERIALIZED(SELECT DISTINCT MID,TRIM(PID) pid FROM M_Cast),source_films AS MATERIALIZED(SELECT DISTINCT c.MID FROM cast_clean c JOIN source s ON c.pid=s.PID),first_hop AS MATERIALIZED(SELECT DISTINCT c.pid FROM cast_clean c JOIN source_films f USING(MID)),next_films AS MATERIALIZED(SELECT DISTINCT c.MID FROM cast_clean c JOIN first_hop h USING(pid)),second_hop AS MATERIALIZED(SELECT DISTINCT c.pid FROM cast_clean c JOIN next_films f USING(MID) EXCEPT SELECT pid FROM first_hop EXCEPT SELECT PID FROM source) """
 query(id,'parent-hop-counts',base+"SELECT 'source' kind,COUNT(*) n FROM source UNION ALL SELECT 'source_films',COUNT(*) FROM source_films UNION ALL SELECT 'first_hop',COUNT(*) FROM first_hop UNION ALL SELECT 'next_films',COUNT(*) FROM next_films UNION ALL SELECT 'second_hop',COUNT(*) FROM second_hop")
 query(id,'parent-hop-person-integrity',base+"SELECT COUNT(*) candidates,SUM(p.PID IS NULL) missing_person FROM second_hop h LEFT JOIN (SELECT DISTINCT PID FROM Person) p ON p.PID=h.pid")
 spec(id,{'population.eligibility':req('最短合作图距离2；排除直接合作者和起点','but not directly with him'),'population.conditions':assume(['源演员按查到的Shah Rukh Khan身份；合演同电影MID，PID外围空白清理']),'population.time':'n/a','measure.formula':assume({'op':'custom','description':'演员电影二分图source电影->一跳PID->其电影->二跳PID，EXCEPT一跳和source，COUNT distinct二跳'}),'measure.countGrain':assume('演员PID一人一次'),'grouping':'n/a','selection':'n/a','output':assume({'rowMode':'scalar','columns':['actors_shahrukh_number_2']})})
 final_freeze(id,base+'SELECT COUNT(*) actors_shahrukh_number_2 FROM second_hop',{'algorithm':'shortest coappearance graph distance exactly2; set difference removes source/direct neighbors','assumptions':['演员业务键PID而不是同名合并'],'limitations':['同名起点若有多个PID需记录实际查询；所有电影均纳入']})
 reveal(id)
elif id=='local196':
 begin(id,{'name':'customers','keyColumns':['customer.customer_id']},'customers','# 独立题解（Gold揭示前）\n每客户先独立合计所有payment.amount，独立数所有rental_id，减一为后续次数。最早payment_date对应payment->rental->inventory->film.rating；不能用最早rental_date替代题面指定payment。先查每客户最早支付有无并列，若并列且rating不同需保留不确定性；主算法按payment_id作为确定性次序，仅在并列情况下起作用。最后在首片rating组对客户总花费与后续次数做等客户权重平均，不在付款/商品连接上直接平均。\n')
 query(id,'parent-sakila-keys',"SELECT 'payment' kind,COUNT(*) n,COUNT(DISTINCT payment_id) ids,COUNT(DISTINCT customer_id) customers FROM payment UNION ALL SELECT 'rental',COUNT(*),COUNT(DISTINCT rental_id),COUNT(DISTINCT customer_id) FROM rental")
 query(id,'parent-first-payment-ties',"WITH first_dates AS(SELECT customer_id,MIN(payment_date) dt FROM payment GROUP BY customer_id),ties AS(SELECT p.customer_id,COUNT(*) n,COUNT(DISTINCT f.rating) ratings FROM payment p JOIN first_dates d ON p.customer_id=d.customer_id AND p.payment_date=d.dt LEFT JOIN rental r ON p.rental_id=r.rental_id LEFT JOIN inventory i ON r.inventory_id=i.inventory_id LEFT JOIN film f ON i.film_id=f.film_id GROUP BY p.customer_id) SELECT COUNT(*) customers,SUM(n>1) ties,SUM(ratings>1) conflicting_ratings,MAX(n) largest_tie FROM ties")
 query(id,'parent-payment-rental-coverage',"WITH rc AS (SELECT customer_id,COUNT(*) rentals FROM rental GROUP BY customer_id),pc AS(SELECT customer_id,COUNT(*) payments,COUNT(DISTINCT rental_id) paid_rentals,SUM(amount) spend FROM payment GROUP BY customer_id) SELECT COUNT(*) customers,SUM(payments!=rentals) unequal_event_counts,SUM(paid_rentals!=rentals) unequal_paid_rentals,MIN(rentals),MAX(rentals) FROM rc JOIN pc USING(customer_id)")
 base="""WITH totals AS MATERIALIZED(SELECT customer_id,SUM(amount) total_spent FROM payment GROUP BY customer_id),rentals AS MATERIALIZED(SELECT customer_id,COUNT(DISTINCT rental_id)-1 subsequent_rentals FROM rental GROUP BY customer_id),first_payment AS MATERIALIZED(SELECT customer_id,rental_id,ROW_NUMBER() OVER(PARTITION BY customer_id ORDER BY payment_date,payment_id) seq FROM payment),first_rating AS MATERIALIZED(SELECT p.customer_id,f.rating FROM first_payment p JOIN rental r ON p.rental_id=r.rental_id JOIN inventory i ON r.inventory_id=i.inventory_id JOIN film f ON i.film_id=f.film_id WHERE p.seq=1),per_customer AS(SELECT f.customer_id,f.rating,t.total_spent,r.subsequent_rentals FROM first_rating f JOIN totals t USING(customer_id) JOIN rentals r USING(customer_id)) """
 query(id,'parent-independent-rating-groups',base+'SELECT rating,COUNT(*) customers,AVG(total_spent) avg_total_spent,AVG(subsequent_rentals*1.0) avg_subsequent_rentals FROM per_customer GROUP BY rating ORDER BY rating')
 spec(id,{'population.eligibility':assume('有可连接首付款租赁影片的客户；各客户在对应首rating组一次'),'population.conditions':assume(['首片由earliest payment_date确定；并列payment_id，若实际无并列则无影响']),'population.time':req('每客户全部记录总额，首事件最早付款日','earliest payment date per customer'),'measure.formula':assume({'op':'custom','description':'每客户SUM(payment.amount)和COUNT DISTINCT rental_id-1；首payment对应film.rating，再按rating等客户权重AVG'}),'measure.countGrain':assume('组内客户等权平均，租赁rental_id计事件'),'measure.denominator':assume('各首rating组客户数'),'grouping':req(['first_film_rating'],'For each rating category of the first movie rented'),'selection':'n/a','output':assume({'rowMode':'grouped','columns':['rating','average_total_spent','average_subsequent_rentals']})})
 final_freeze(id,base+'SELECT rating,AVG(total_spent) average_total_spent,AVG(subsequent_rentals*1.0) average_subsequent_rentals FROM per_customer GROUP BY rating ORDER BY rating',{'algorithm':'separate customer payment sum and rental count; first film by earliest payment, then per-rating customer averages','assumptions':['同付款时间用payment_id确定；实际先查询并列'],'limitations':['未凭Gold改为租赁日期或删部分月份']})
 reveal(id)
